<script setup lang="ts">
import { onMounted,ref } from 'vue';import dayjs from 'dayjs';import { http } from '../api/http';type Notice={id:number;title:string;content:string;read:boolean;createdAt:string};const rows=ref<Notice[]>([]);async function load(){rows.value=(await http.get('/notifications')).data}async function read(row:Notice){if(!row.read){await http.post(`/notifications/${row.id}/read`);row.read=true}}onMounted(load);
</script>
<template><div class="page"><div class="page-header"><div><h2>站内通知</h2><p>查看预约提交、审批和状态变化提醒</p></div><el-tag>{{rows.filter(x=>!x.read).length}} 条未读</el-tag></div><section class="panel notice-list"><article v-for="item in rows" :key="item.id" :class="{unread:!item.read}" @click="read(item)"><i></i><div><strong>{{item.title}}</strong><p>{{item.content}}</p><small>{{dayjs(item.createdAt).format('YYYY-MM-DD HH:mm')}}</small></div><el-tag v-if="!item.read" size="small">未读</el-tag></article><el-empty v-if="!rows.length" description="暂无通知"/></section></div></template><style scoped>.notice-list{padding:0 22px}.notice-list article{display:grid;grid-template-columns:10px 1fr auto;gap:14px;align-items:start;padding:20px 4px;border-bottom:1px solid #edf0f4;cursor:pointer}.notice-list article i{width:8px;height:8px;border-radius:50%;background:#d4dbe5;margin-top:5px}.notice-list article.unread i{background:#3974e8}.notice-list p{color:#6f7c90;margin:7px 0;font-size:13px}.notice-list small{color:#a0a8b5}</style>
